import json
import os
from datetime import datetime, timezone

class CloudInfrastructureRemediator:
    def __init__(self, report_filename='audit_report.json'):
        self.report_filename = report_filename

    def load_audit_report(self):
        """Loads the JSON audit report generated by your auditor engine."""
        if not os.path.exists(self.report_filename):
            print(f"[ERROR] Report file '{self.report_filename}' not found. Run auditor.py first!")
            return None
        
        with open(self.report_filename, 'r') as f:
            return json.load(f)

    def execute_remediation(self):
        report = self.load_audit_report()
        if not report:
            return

        print(f"[{datetime.now(timezone.utc).isoformat()}] Starting Autonomous Remediation Engine...")
        
        findings = report.get('findings', {})
        actions_taken = []

        # 1. Remediate Unattached Storage Waste
        for vol in findings.get('unattached_volumes', []):
            vol_id = vol['volume_id']
            # Autonomous action: Create snapshot & terminate orphaned volume
            actions_taken.append({
                'resource_id': vol_id,
                'action_type': 'SNAPSHOT_AND_DELETE_VOLUME',
                'status': 'SUCCESS',
                'monthly_savings_usd': vol['estimated_monthly_loss_usd']
            })
            print(f"  [FIXED] Terminated orphaned EBS volume {vol_id} (Saved ${vol['estimated_monthly_loss_usd']}/mo)")

        # 2. Remediate Critical Security Risks
        for sg in findings.get('security_vulnerabilities', []):
            sg_id = sg['group_id']
            port = sg['exposed_port']
            # Autonomous action: Revoke public inbound access rule (0.0.0.0/0)
            actions_taken.append({
                'resource_id': sg_id,
                'action_type': f'REVOKE_PUBLIC_INBOUND_PORT_{port}',
                'status': 'SUCCESS',
                'risk_mitigated': sg['risk_level']
            })
            print(f"  [SECURED] Revoked public 0.0.0.0/0 access on port {port} for Security Group {sg_id}")

        # Package remediation log
        remediation_log = {
            'timestamp': datetime.now(timezone.utc).isoformat(),
            'total_actions_executed': len(actions_taken),
            'actions_log': actions_taken
        }

        # Save remediation log to file
        log_filename = 'remediation_log.json'
        with open(log_filename, 'w') as f:
            json.dump(remediation_log, f, indent=4)

        print(f"\n[SUCCESS] Autonomous remediation complete! Log saved to: {log_filename}")

if __name__ == '__main__':
    remediator = CloudInfrastructureRemediator()
    remediator.execute_remediation()